diff --git a/scripts/check-stripe-endive.js b/scripts/check-stripe-endive.js
new file mode 100644
index 0000000..f596df6
--- /dev/null
+++ b/scripts/check-stripe-endive.js
@@ -0,0 +1,12 @@
+const fs = require("fs");
+const assert = require("assert");
+const read = (p) => fs.readFileSync(p, "utf8");
+const v = JSON.parse(read("node_modules/stripe/package.json")).version;
+assert(v.startsWith("23."), "stripe 23 installed, got " + v);
+assert(!read("app/api/stripe/generate-checkout/route.ts").includes("payment_method_types"));
+for (const f of ["lib/stripe.ts", "lib/stripe/getOrCreateCustomer.ts"]) {
+  const s = read(f);
+  assert(s.includes("2026-09-30.endive"), f);
+  assert(!s.includes("2025-04-30.basil"), f);
+}
+console.log("ok");
